/**
 * Generates drizzle/0006_sync_outbox.sql: the outbox the sync engine pushes from.
 * Triggers log every insert/update of a synced table, except while the engine itself is
 * applying rows pulled from the server (local_meta 'sync_applying' is set then), so pulled
 * changes don't echo back. Existing rows are queued once, so the server gets the seed layout.
 *   node scripts/build-sync-sql.mjs
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { SYNC_TABLES } from '../../../packages/shared/src/sync.ts';

const out = [
  [
    '-- Generated by scripts/build-sync-sql.mjs. Do not edit by hand.',
    'CREATE TABLE `sync_outbox` (`id` integer PRIMARY KEY AUTOINCREMENT, `table_name` text NOT NULL, `row_id` text NOT NULL);',
  ].join('\n'),
];
const quiet = "(SELECT `value` FROM `local_meta` WHERE `key` = 'sync_applying') IS NULL";
for (const t of SYNC_TABLES.filter((t) => t.mode !== 'pull')) {
  for (const [op, when] of [
    ['ins', 'INSERT'],
    ['upd', 'UPDATE'],
  ]) {
    out.push(
      `CREATE TRIGGER \`sync_${t.name}_${op}\` AFTER ${when} ON \`${t.name}\` WHEN ${quiet} BEGIN INSERT INTO \`sync_outbox\` (\`table_name\`, \`row_id\`) VALUES ('${t.name}', NEW.\`id\`); END;`,
    );
  }
  out.push(`INSERT INTO \`sync_outbox\` (\`table_name\`, \`row_id\`) SELECT '${t.name}', \`id\` FROM \`${t.name}\`;`);
}
const target = fileURLToPath(new URL('../drizzle/0006_sync_outbox.sql', import.meta.url));
writeFileSync(target, out.join('\n--> statement-breakpoint\n') + '\n');
console.log(`wrote ${out.length} statements to ${target}`);
